parameters.jsCode:
const cfg = $('⚙️ Config').first().json;
const listName = $('Xác Định Tên List').first().json.resolved_list_name || cfg.list_id;
return [{ json: { chatId: cfg.notifyChatId || cfg.ADMIN_CHAT_ID, text: `🚀 <b>Bắt đầu đồng bộ ClickUp → Postgres</b>
📋 List: <b>${listName}</b> (ID: ${cfg.list_id})
🕒 Bắt đầu lúc: ${new Date().toLocaleString('vi-VN')}
${cfg.testMode ? '⚠️ TEST MODE' : '📦 Full data'}` } }];

const cfg = $('⚙️ Config').first().json;
const t = $json;
const fieldNameMap = cfg.fieldNameMap;

const normalize = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/\u0111/g, 'd').replace(/\u0110/g, 'D').toLowerCase();

function getCF(customFields, name) {
  if (!Array.isArray(customFields) || !name) return null;
  const f = customFields.find(cf => (cf.name || '').trim().toLowerCase() === name.trim().toLowerCase());
  if (!f || f.value === undefined || f.value === null) return null;
  if (f.type === 'list_relationship' && Array.isArray(f.value)) {
    return f.value.map(v => v.status ? `${v.name} (${v.status})` : v.name).join('; ');
  }
  if (f.type === 'date' || /^\d{10,13}$/.test(String(f.value))) {
    const d = new Date(Number(f.value));
    if (!isNaN(d.getTime())) {
      const dd = String(d.getDate()).padStart(2, '0');
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      return `${dd}/${mm}/${d.getFullYear()}`;
    }
  }
  if (typeof f.value === 'object') return JSON.stringify(f.value);
  return String(f.value);
}

const cfs = t.custom_fields || [];
let phuTrach = getCF(cfs, fieldNameMap.phu_trach) || '';
if (!phuTrach && Array.isArray(t.assignees) && t.assignees.length > 0) {
  phuTrach = t.assignees.map(a => a.username || a.email).filter(Boolean).join(', ');
}

return {
  json: {
    id: t.id, name: t.name || '', name_khong_dau: normalize(t.name || ''), url: t.url || '',
    description: t.text_content || t.description || '', status: t.status?.status || '',
    team_id: t.team_id || cfg.team_id, space_id: t.space?.id || cfg.space_id,
    folder_id: t.folder?.id || '', folder_name: t.folder?.name || '',
    list_id: t.list?.id || cfg.list_id, list_name: t.list?.name || '',
    phu_trach: phuTrach,
    b1_datum: getCF(cfs, fieldNameMap.b1_datum) || '', dob: getCF(cfs, fieldNameMap.dob) || '',
    ma_hd: getCF(cfs, fieldNameMap.ma_hd) || '', nghe: getCF(cfs, fieldNameMap.nghe) || '',
    sdt: getCF(cfs, fieldNameMap.sdt) || '', email: getCF(cfs, fieldNameMap.email) || '',
    dia_chi_vn: getCF(cfs, fieldNameMap.dia_chi_vn) || '', vfs: getCF(cfs, fieldNameMap.vfs) || '',
    du_kien_den_duc: getCF(cfs, fieldNameMap.du_kien_den_duc) || '',
    ngay_xuat_canh: getCF(cfs, fieldNameMap.ngay_xuat_canh) || '',
    dkpv_2026: getCF(cfs, fieldNameMap.dkpv_2026) || '', pvtc_2026: getCF(cfs, fieldNameMap.pvtc_2026) || '',
    nha_cua_support: getCF(cfs, fieldNameMap.nha_cua_support) || '',
    dkpv: getCF(cfs, fieldNameMap.dkpv) || '', pvtc: getCF(cfs, fieldNameMap.pvtc) || '',
    vfs_khong_dau: getCF(cfs, fieldNameMap.vfs_khong_dau) || '',
    planbay: getCF(cfs, fieldNameMap.planbay) || '', ngaybay: getCF(cfs, fieldNameMap.ngaybay) || '',
    color: getCF(cfs, fieldNameMap.color) || '', other_link: getCF(cfs, fieldNameMap.other_link) || '',
    onedrive_link: getCF(cfs, fieldNameMap.onedrive_cf) || '',
    youtube_link: getCF(cfs, fieldNameMap.youtube_cf) || '',
    date_updated: t.date_updated ? new Date(Number(t.date_updated)).toISOString() : null,
  }
};

const items = $input.all();
const URL_RE = /https?:\/\/[^\s)"'\]]+/g;
function classifyLink(url) {
  const u = url.toLowerCase();
  if (u.includes('onedrive.live.com') || u.includes('1drv.ms') || u.includes('sharepoint.com')) return 'onedrive';
  if (u.includes('youtube.com') || u.includes('youtu.be')) return 'youtube';
  return null;
}
const results = [];
for (let idx = 0; idx < items.length; idx++) {
  const c = items[idx].json;
  let taskId = c.task_id || c.task?.id || null;
  if (!taskId) {
    try { taskId = $('ClickUp - Get Tasks').itemMatching(idx).json.id; } catch (e) { continue; }
  }
  if (!taskId) continue;
  let link = null, kind = null;
  const segs = Array.isArray(c.comment) ? c.comment : [];
  for (const seg of segs) {
    const candidate = seg.bookmark?.url || seg.attributes?.link;
    if (candidate) { const k = classifyLink(candidate); if (k) { link = candidate; kind = k; break; } }
  }
  if (!link) {
    const plain = c.comment_text || '';
    for (const url of (plain.match(URL_RE) || [])) {
      const k = classifyLink(url); if (k) { link = url; kind = k; break; }
    }
  }
  if (link) results.push({ json: { taskId, link, kind } });
}
if (results.length === 0) return [{ json: { taskId: null, link: null, kind: null } }];
return results;

const cfg = $('⚙️ Config').first().json;
const chatId = cfg.notifyChatId || cfg.ADMIN_CHAT_ID;
const rows = $input.all().map(i => i.json);

const totalByList = {};
for (const r of rows) totalByList[r.list_name] = (totalByList[r.list_name] || 0) + r.cnt;

const statusEmoji = (status) => {
  const s = (status || '').toLowerCase();
  if (s.includes('xử lý') || s.includes('xu ly')) return '⚙️';
  if (s.includes('ready') || s.includes('sẵn sàng')) return '✅';
  if (s.includes('lỗi') || s.includes('loi')) return '❌';
  if (s.includes('chờ') || s.includes('cho')) return '⏳';
  return '🔹';
};

let text = `✅ <b>Đồng bộ ClickUp → Postgres HOÀN TẤT</b>\n\n`;
for (const [listName, total] of Object.entries(totalByList)) {
  text += `📋 <b>${listName}</b>: <b>${total}</b> task\n`;
  rows.filter(r => r.list_name === listName)
      .forEach(r => { text += `   ${statusEmoji(r.status)} ${r.status || 'Không rõ'}: ${r.cnt}\n`; });
  text += `\n`;
}
text += `🕒 Kết thúc lúc: ${new Date().toLocaleString('vi-VN')}\n#full_reconcile_done`;
return [{ json: { chatId, text } }];

parameters.query:
SELECT COALESCE(
  NULLIF($2, ''),
  (SELECT list_name FROM clickup.sync_targets WHERE list_id = $1 LIMIT 1),
  $1
) AS resolved_list_name;

parameters.jsCode:
// Trich xuat cau truc lien ket DKPV/PVTC tu task student, ghi thanh tung dong rieng thay vi
// gop chuoi text - de dem chinh xac + tao duoc deep-link toi task Don Hang lien quan.
// PVTC doi ten field theo NAM (PVTC 2026, PVTC 2027...) - dung REGEX nhan dien TU DONG,
// khong hardcode ten field, nam sau ClickUp them field moi KHONG can sua code.
const t = $('ClickUp - Get Tasks').item.json;
const cfs = t.custom_fields || [];

function extractLinks(field, linkType, pvtcYear) {
  if (!field || !Array.isArray(field.value)) return [];
  return field.value.map(v => ({
    order_task_id: v.id,
    order_task_name: v.name || '',
    order_task_status: v.status || '',
    link_type: linkType,
    pvtc_year: pvtcYear,
  }));
}

let links = [];

// DKPV - ten field CO DINH, khong doi theo nam
const dkpvField = cfs.find(cf => (cf.name || '').trim().toLowerCase() === 'dkpv');
links = links.concat(extractLinks(dkpvField, 'dkpv', null));

// PVTC - ten field DOI THEO NAM, quet TOAN BO custom_fields tim field khop mau "PVTC <nam>"
const PVTC_RE = /^PVTC\s+(\d{4})$/i;
for (const cf of cfs) {
  const m = (cf.name || '').trim().match(PVTC_RE);
  if (m) {
    const year = parseInt(m[1], 10);
    links = links.concat(extractLinks(cf, 'pvtc', year));
  }
}

return { json: { taskId: t.id, linksJson: JSON.stringify(links) } };
